// ===== 1. 可辨识联合（Discriminated Union）+ switch 收窄 =====
type Shape =
  | { kind: 'circle'; radius: number }
  | { kind: 'rect'; width: number; height: number }
  | { kind: 'triangle'; base: number; height: number };

function calcArea(s: Shape): number {
  switch (s.kind) {
    case 'circle':
      return Math.PI * s.radius ** 2; // s 已收窄为 circle 分支，可安全访问 radius
    case 'rect':
      return s.width * s.height;
    case 'triangle':
      return (s.base * s.height) / 2;
    default: {
      // 穷尽性检查：所有分支处理完后，s 必须是 never
      // 若未来新增 kind 却忘了处理，这里会直接编译报错
      const _exhaustive: never = s;
      throw new Error(`未处理的形状: ${JSON.stringify(_exhaustive)}`);
    }
  }
}

// ===== 2. 自定义类型守卫（type predicate） =====
type Ok<T> = { ok: true; value: T };
type Err = { ok: false; message: string };
type Result<T> = Ok<T> | Err;

function isOk<T>(r: Result<T>): r is Ok<T> {
  return r.ok === true;
}

function unwrap<T>(r: Result<T>): T {
  if (isOk(r)) {
    return r.value; // 这里 r 自动收窄为 Ok<T>
  }
  throw new Error(r.message); // 否则分支收窄为 Err
}

// ===== 3. 断言函数（asserts x is T） =====
function assertDefined<T>(
  v: T | null | undefined,
  msg = '值不能为空'
): asserts v is T {
  if (v === null || v === undefined) throw new Error(msg);
}

// ===== 4. 内置收窄：typeof / Array.isArray =====
function describe(input: string | number | string[]): string {
  if (Array.isArray(input)) return `数组，长度 ${input.length}`;
  if (typeof input === 'string') return `字符串：${input}`;
  return `数字：${input.toFixed(2)}`; // 剩余分支收窄为 number
}

// ===== 运行演示 =====
const shapes: Shape[] = [
  { kind: 'circle', radius: 2 },
  { kind: 'rect', width: 3, height: 4 },
  { kind: 'triangle', base: 6, height: 5 },
];
console.log(shapes.map((s) => calcArea(s)));
// => [ 12.566..., 12, 15 ]

const r: Result<number> = { ok: true, value: 42 };
console.log(unwrap(r)); // => 42

const maybePort: number | undefined = 8080;
assertDefined(maybePort, '缺少 port');
console.log(maybePort + 1); // 断言后 maybePort 收窄为 number，可直接做运算
// => 8081

console.log(describe('hi'), describe(3.14159), describe(['a']));
// => 字符串：hi 数字：3.14 数组，长度 1

